entries[332074] = { ["name"] = "Shadowghast Ring", ["text"] = "2.5 sec cast 2\nTools: Jeweler's Tools\nReagents:\nShadowghast Ingot (50), Essence of Rebirth (25), Essence of Torment (25), Orboreal Shard (25)\nOptional Reagents:\nIncrease Rank (#78)\nCreate a piece of jewelry that is worthy of being infused with the power necessary to become a Legendary item.\nUnique-Equipped: Shadowlands Crafted Legendary (1)Finger\n+17 Stamina\n+ 28 Random Stat 1\n+ 28 Random Stat 2\n60\n\"An exceptionally well crafted piece of jewelry worthy of being empowered by the Runecarver.\"" }
entries[332075] = { ["name"] = "Shadowghast Necklace", ["text"] = "2.5 sec cast 2\nTools: Jeweler's Tools\nReagents:\nShadowghast Ingot (50), Essence of Servitude (25), Essence of Valor (25), Orboreal Shard (25)\nOptional Reagents:\nIncrease Rank (#78)\nCreate a piece of jewelry that is worthy of being infused with the power necessary to become a Legendary item.\nUnique-Equipped: Shadowlands Crafted Legendary (1)Neck\n+17 Stamina\n+ 28 Random Stat 1\n+ 28 Random Stat 2\n60\n\"An exceptionally well crafted piece of jewelry worthy of being empowered by the Runecarver.\"" }
