entries[332243] = { ["name"] = "Shadeleaf Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The shadeleaf runestag are bred for their ferocity as well as their beauty by the Wild Hunt. They feel no fear charging into the den of any predator.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[332244] = { ["name"] = "Wakener's Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Runestags enjoy lying near wildseeds. The Wakeners believe they can hear the sleepers' dreams. These runestags display a range of emotions in their vigil, signaling the dreams or nightmares of the spirits within.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[332245] = { ["name"] = "Winterborn Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Winterborn runestags are blessed by the Winter Queen herself. Their runes flare brilliantly when predators are nearby, warning the entire herd.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[332246] = { ["name"] = "Enchanted Shadeleaf Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"A shadeleaf runestag is capable of goring creatures as powerful as a gorm matriarch in defense of its herd. The Wild Hunt ride these mounts into dangerous corners of the Shadowlands, when their domain must be defended from those who would threaten the wilds.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[332247] = { ["name"] = "Enchanted Wakener's Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Wakener runestags fiercely protect their wildseed groves. When the groves starting to fail, many runestags went berserk.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[332248] = { ["name"] = "Enchanted Winterborn Runestag", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Winterborn runestags are the favored mount of the Winter Queen herself, and she only bestows such a creature on her most favored subjects.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
